# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 minae / minari','威胁；威吓']]
N=B+[['拉丁 minax → minacia → 古法语 menace','带威胁的 → 威胁之物、威胁'],['英语 menace 名词','威胁；造成麻烦的人或物']]
V=B+[['古法语 menacier / menacer → 英语 menace 动词','威吓、威胁']]
W=[
E('menace','/ˈmenɪs/','威胁；危险的人或物；使人头疼的人或物；威胁、恐吓','让人感觉要出事的存在；语气轻时，也可以指总惹麻烦的家伙。','名词经古法语 menace 来自拉丁 minacia 一支，关联 minari 威胁；动词经古法语 menacier 等形式进入。名词与动词不是凭现代拼写就能判定谁由谁转成。',N+[V[-1]],'a menace to public safety 指危害公共安全的人或物。You’re a menace! 在熟人之间也可半开玩笑说你真会添乱。动词 menace 则偏正式，表示使某人或某地面临危险。轻重差别很大，要看对象与场景。','a menace to society；a sense of menace；menace a community。','danger 是危险本身，a menace 常把造成危险的来源当成一个对象。表示扬言去做某事，一般用 threaten to do，不照搬成 menace to do。',('Reckless driving is a menace to everyone on the road.','鲁莽驾驶会危及路上的每一个人。'),('That puppy is a little menace whenever the kitchen door is open.','厨房门一开，那只小狗就成了捣蛋鬼。'),('Floodwaters menaced several villages downstream.','洪水威胁着下游的几个村庄。'),sources=['https://www.etymonline.com/word/menace','https://www.oxfordlearnersdictionaries.com/definition/english/menace_1','https://www.oxfordlearnersdictionaries.com/definition/english/menace_2']),
E('menacing','/ˈmenəsɪŋ/','带威胁的；令人感到危险的','危险还不一定发生，但眼神、声音或景象已经让人绷紧神经。','英语 menace 去掉末尾 e 加 -ing，分词进一步用作形容词。形容某种表现仿佛在威胁人。',V+[['英语 menace → menacing','威胁 → 显得带威胁的']],'a menacing tone 是听着让人担心会受害的语气，menacing clouds 则把乌云写得像逼近的危险。这个词强调呈现出来的压迫感，并不是说事情已经造成了伤害。','a menacing look；a menacing tone；look menacing。','menacing 是看起来可能带来危险，menaced 是已经受到威胁。the menacing dog 指看着有威胁的狗，不能据此说它已经被威胁了。',('His voice became low and menacing.','他的声音变得低沉，带着威胁意味。'),('Dark, menacing clouds gathered above the ridge.','阴沉、令人不安的乌云聚集在山脊上方。'),sources=['https://www.etymonline.com/word/menacing','https://www.oxfordlearnersdictionaries.com/definition/english/menacing']),
E('menacingly','/ˈmenəsɪŋli/','带着威胁地；令人不安地','让靠近、盯视或发声这个动作带上“恐怕要出事”的气氛。','英语 menacing + -ly，由带威胁的形容词形成方式副词。',V+[['英语 menacing → menacingly','带威胁的 → 以这种方式行动']],'它常跟 move、stare、growl 等动作连用，让读者感觉到动作的威胁意味。一个角色只是靠近，本来可以很中性；加上 menacingly，就把场面写成逼近和压迫。文学描写也可用在天气或机器声音上。','move menacingly；stare menacingly；growl menacingly。','angrily 表示愤怒，menacingly 表示显露危险或威胁。一个人可以冷静、低声地威胁别人，并没有大喊大叫。',('The guard stepped menacingly towards the intruder.','守卫带着威慑意味向闯入者逼近。'),('The dog growled menacingly from behind the gate.','那只狗在门后发出带威胁的低吼。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/american_english/menacing','https://www.collinsdictionary.com/us/dictionary/english/menacingly'])
]
ROOT=dict(id='C0745',meaning='威胁；威吓；由威吓引出的驱赶、引导',core='MINA = THREATEN',image='起点是让人害怕、催人行动；一支保留威胁，另一支经驱赶、引导走到举止和散步。',intro='拉丁 minari 表示威胁，minae 是威胁。menace 一组最直接保留这层意思。另一些后代经过威吓驱赶动物、引导行动的中间环节，发展成 demeanor 和 promenade 等看似毫不吓人的词，需沿完整路线理解。',forms='menace 名词与动词各经法语形式进入，menacing、menacingly 是英语派生。demeanor 经 demener 引导、举止这一支；promenade 经 prominare、se promener 走向散步，再缩短成 prom。不能把每个现代词都直接翻成威胁。',branches=[['危险与威胁感','menace、menacing、menacingly'],['引导行为到外在举止','demeanor、demeanour'],['驱赶前行到散步、舞会','promenade、prom']],contrasts='现代 menace 的危险感不能硬套到 demeanor 或 prom 上；中间的驱赶、引导、行走才是连接不同词义的关键。menacing 还强调显现的威胁感，不等于伤害已经发生。',practice='His calm demeanor contrasted with the menacing tone of the message.\n\n他平静的举止与那条消息中带威胁的语气形成对比。',words=[x['word'] for x in W]+['demeanor','demeanour','promenade','prom'],exclude={'minatory':'较冷门的正式近义形容词，先掌握更常用的 menacing'})
if __name__=='__main__':
 for name,data in [('roots_mina',[ROOT]),('words_mina',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
